// Merge the caller's input with the configuration read from the database.
// Nothing here is hardcoded: provider, model and endpoint all come from
// app_settings, so switching provider is a database update, not a workflow edit.
const cfg = $('Load config').first().json;
const input = $('When Executed by Another Workflow').first().json;

if (!cfg.provider || !cfg.model) {
  throw new Error('llm_provider or llm_model missing from app_settings.');
}

return [{
  json: {
    task: input.task || 'unknown',
    item_id: input.item_id ?? null,
    system_prompt: input.system_prompt || 'Tiivista seuraava teksti lyhyesti suomeksi.',
    user_text: input.user_text || '',
    provider: cfg.provider,
    model: cfg.model,
    base_url: cfg.base_url,
    cache_enabled: cfg.cache_enabled === 'true',
    max_output_tokens: Number(cfg.max_output_tokens) || 400,
  }
}];

// Return the cached response if we have one, otherwise call the provider.
// This is the only place in the project that talks to a model, which is what
// makes cost measurable in one place and the provider swappable.
const req = $('Prepare request').first().json;
const rows = $input.all();
const cached = rows.length ? rows[0].json : null;

if (req.cache_enabled && cached && cached.response) {
  // Only whole answers are cached, so a hit is never truncated.
  return [{ json: { ...req, text: cached.response, tokens_in: cached.tokens_in,
                    tokens_out: cached.tokens_out, duration_ms: 0, cached: true,
                    truncated: false } }];
}

const started = Date.now();
let text = '', tokensIn = null, tokensOut = null, truncated = false;

if (req.provider === 'ollama') {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `${req.base_url}/api/generate`,
    body: {
      model: req.model,
      prompt: `${req.system_prompt}\n\n${req.user_text}`,
      stream: false,
      options: { num_predict: req.max_output_tokens },
    },
    json: true,
    timeout: 180000,
  });
  text = (res.response || '').trim();
  tokensIn = res.prompt_eval_count ?? null;
  tokensOut = res.eval_count ?? null;
  // 'length' means it stopped because it ran out of room, not because it
  // finished. The text will end mid-sentence and look complete otherwise.
  truncated = res.done_reason === 'length';
} else {
  // Add the commercial provider here when we have a key. Keep the shape of
  // the returned object identical so nothing downstream has to change.
  throw new Error(`Provider "${req.provider}" is not implemented yet. Set llm_provider in app_settings.`);
}

return [{ json: { ...req, text, tokens_in: tokensIn, tokens_out: tokensOut,
                  duration_ms: Date.now() - started, cached: false, truncated } }];

// The shape every caller gets back. Keep this stable.
//
// task and item_id are echoed straight back from what the caller sent. A
// caller gets one item out of this workflow and loses whatever it was holding,
// so without these it has the model's answer and nothing to match it against.
// Join on item_id, or reach back to your own earlier node.
const r = $('Call model').first().json;
const req = $('Prepare request').first().json;
const logged = $input.first().json || {};

return [{
  json: {
    task: req.task,
    item_id: req.item_id,
    text: r.text,
    provider: r.provider,
    model: r.model,
    tokens_in: r.tokens_in,
    tokens_out: r.tokens_out,
    cost_eur: logged.estimated_cost_eur ?? null,
    duration_ms: r.duration_ms,
    cached: r.cached,
    // true means the model ran out of room and the text stops mid-sentence.
    truncated: r.truncated === true,
  }
}];
